    std::vector<long long> a(n);
    for (auto &x : a) std::cin >> x;
    PersistentKth tree(a);
    while (m--)
    {
        int l, r, k;
        std::cin >> l >> r >> k;
        std::cout << tree.kth(l, r, k) << '\n';
    }
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct TreePathKth
{
    using ll = long long;

    struct Node
    {
        int l = 0, r = 0, sum = 0;
    };

    int n, lg;
    vector<vector<int>> g, up;
    vector<int> root, dep;
    vector<ll> value, vals;
    vector<Node> t;

    TreePathKth(const vector<ll> &a)
        : n(a.size()), g(n + 1), root(n + 1), dep(n + 1), value(a)
    {
        assert(n > 0);
        lg = 1;
        while ((1LL << lg) <= n) lg++;
        up.assign(lg, vector<int>(n + 1));
    }

    void add(int u, int v)
    {
        g[u].push_back(v);
        g[v].push_back(u);
    }

    int insert(int old, int l, int r, int x)
    {
        int p = t.size();
        Node copy = t[old];
        t.push_back(copy);
        t[p].sum++;
        if (l == r) return p;
        int m = (l + r) / 2;
        if (x <= m)
        {
            int child = insert(t[old].l, l, m, x);
            t[p].l = child;
        }
        else
        {
            int child = insert(t[old].r, m + 1, r, x);
            t[p].r = child;
        }
        return p;
    }

    void dfs(int u, int p)
    {
        up[0][u] = p;
        for (int j = 1; j < lg; j++) up[j][u] = up[j - 1][up[j - 1][u]];
        int x = lower_bound(vals.begin(), vals.end(), value[u - 1]) - vals.begin();
        root[u] = insert(root[p], 0, (int)vals.size() - 1, x);
        for (int v : g[u])
        {
            if (v == p) continue;
            dep[v] = dep[u] + 1;
            dfs(v, u);
        }
    }

    void build(int r = 1)
    {
        assert(1 <= r && r <= n);
        vals = value;
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        t.assign(1, Node{});
        dep[r] = 0;
        dfs(r, 0);
    }

    int lca(int u, int v) const
    {
        if (dep[u] < dep[v]) swap(u, v);
        int diff = dep[u] - dep[v];
        for (int j = 0; j < lg; j++)
            if (diff >> j & 1) u = up[j][u];
        if (u == v) return u;
        for (int j = lg - 1; j >= 0; j--)
            if (up[j][u] != up[j][v])
            {
                u = up[j][u];
                v = up[j][v];
            }
        return up[0][u];
    }

    ll kth(int u, int v, int k) const
    {
        int z = lca(u, v);
        assert(1 <= k && k <= dep[u] + dep[v] - 2 * dep[z] + 1);
        int a = root[u], b = root[v], c = root[z], d = root[up[0][z]];
        int l = 0, r = (int)vals.size() - 1;
        while (l < r)
        {
            int count = t[t[a].l].sum + t[t[b].l].sum - t[t[c].l].sum - t[t[d].l].sum;
            int m = (l + r) / 2;
            if (k <= count)
            {
                a = t[a].l;
                b = t[b].l;
                c = t[c].l;
                d = t[d].l;
                r = m;
            }
            else
            {
                k -= count;
                a = t[a].r;
                b = t[b].r;
                c = t[c].r;
                d = t[d].r;
                l = m + 1;
            }
        }
        return vals[l];
    }
};

int main()
{
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n, m;
    std::cin >> n >> m;
    std::vector<long long> a(n);
    for (auto &x : a) std::cin >> x;
    TreePathKth tree(a);
    for (int i = 1; i < n; i++)
    {
        int u, v;
        std::cin >> u >> v;
        tree.add(u, v);
    }
    tree.build();
    long long last = 0;
    while (m--)
    {
        long long encoded;
        int v, k;
        std::cin >> encoded >> v >> k;
        int u = encoded ^ last;
        last = tree.kth(u, v, k);
        std::cout << last << '\n';
    }
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct PositionBasis
{
    using U = unsigned long long;
    U a[64]{};
    int pos[64];

    PositionBasis() { fill(pos, pos + 64, -1); }

    void insert(U x, int at)
    {
        assert(at >= 0);
        for (int i = 63; i >= 0; i--)
            if (x >> i & 1)
            {
                if (!a[i])
                {
                    a[i] = x;
                    pos[i] = at;
                    return;
                }
                if (at > pos[i])
                {
                    swap(a[i], x);
                    swap(pos[i], at);
                }
                x ^= a[i];
            }
    }

    bool contains(U x, long long lower = 0) const
    {
        assert(lower >= 0);
        for (int i = 63; i >= 0; i--)
            if ((x >> i & 1) && pos[i] >= lower) x ^= a[i];
        return x == 0;
    }

    U query(long long lower = 0, U x = 0) const
    {
        assert(lower >= 0);
        for (int i = 63; i >= 0; i--)
            if (pos[i] >= lower) x = max(x, x ^ a[i]);
        return x;
    }

    int rank(long long lower = 0) const
    {
        assert(lower >= 0);
        int answer = 0;
        for (int i = 0; i < 64; i++) answer += pos[i] >= lower;
        return answer;
    }
};

int main()
{
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n, q;
    std::cin >> n;
    std::vector<unsigned long long> a(n + 1);
    for (int i = 1; i <= n; i++) std::cin >> a[i];
    std::cin >> q;
    std::vector<std::array<int, 3>> queries(q);
    for (int i = 0; i < q; i++)
    {
        int l, r;
        std::cin >> l >> r;
        queries[i] = {r, l, i};
    }
    std::sort(queries.begin(), queries.end());
    std::vector<unsigned long long> answer(q);
    PositionBasis basis;
    int right = 0;
    for (auto [r, l, id] : queries)
    {
        while (right < r)
        {
            right++;
            basis.insert(a[right], right);
        }
        answer[id] = basis.query(l);
    }
    for (auto x : answer) std::cout << x << '\n';
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct Lucas
{
    int mod;
    vector<int> fac, ifac;

    Lucas(int p)
    {
        assert(p >= 2);
        mod = p;
        fac.resize(p);
        ifac.resize(p);
        fac[0] = 1;
        for (int i = 1; i < p; i++) fac[i] = 1LL * fac[i - 1] * i % p;
        long long a = fac[p - 1], r = 1;
        for (int e = p - 2; e; e >>= 1)
        {
            if (e & 1) r = r * a % p;
            a = a * a % p;
        }
        ifac[p - 1] = r;
        for (int i = p - 1; i; i--) ifac[i - 1] = 1LL * ifac[i] * i % p;
    }

    int choose(unsigned long long n, unsigned long long k) const
    {
        if (k > n) return 0;
        long long answer = 1;
        while (n || k)
        {
            int a = n % mod, b = k % mod;
            if (b > a) return 0;
            answer = answer * fac[a] % mod;
            answer = answer * ifac[b] % mod;
            answer = answer * ifac[a - b] % mod;
            n /= mod;
            k /= mod;
        }
        return answer;
    }
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--)
    {
        unsigned long long n, m;
        int p;
        cin >> n >> m >> p;
        Lucas solver(p);
        cout << solver.choose(n + m, n) << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct ExLucas
{
    using ull = unsigned long long;
    using ll = long long;

    struct Factor
    {
        int p, q, exponent, start, crt;
    };

    int mod;
    vector<int> fac;
    vector<Factor> factors;

    static ll power(ll a, ull b, int m)
    {
        ll result = 1;
        while (b)
        {
            if (b & 1) result = result * a % m;
            a = a * a % m;
            b >>= 1;
        }
        return result;
    }

    ExLucas(int m) : mod(m)
    {
        assert(m >= 1);
        int x = m;
        for (int p = 2; p <= x / p; p++)
        {
            if (x % p) continue;
            int q = 1, e = 0;
            do
            {
                x /= p;
                q *= p;
                e++;
            } while (x % p == 0);
            add_factor(p, q, e);
        }
        if (x > 1) add_factor(x, x, 1);
    }

    void add_factor(int p, int q, int e)
    {
        int start = fac.size();
        fac.push_back(1);
        for (int i = 1; i < q; i++) fac.push_back(ll(fac.back()) * (i % p ? i : 1) % q);
        fac.push_back(fac.back());
        int phi = q - q / p;
        int crt = ll(mod / q) * power(mod / q % q, phi - 1, q) % mod;
        factors.push_back({p, q, e, start, crt});
    }

    static ull valuation(ull n, int p)
    {
        ull result = 0;
        while (n)
        {
            n /= p;
            result += n;
        }
        return result;
    }

    ll unit(ull n, const Factor &f) const
    {
        ll result = 1;
        while (n)
        {
            result = result * power(fac[f.start + f.q], n / f.q, f.q) % f.q;
            result = result * fac[f.start + n % f.q] % f.q;
            n /= f.p;
        }
        return result;
    }

    int choose(ull n, ull k) const
    {
        if (k > n || mod == 1) return 0;
        ll answer = 0;
        for (const auto &f : factors)
        {
            ull e = valuation(n, f.p) - valuation(k, f.p) - valuation(n - k, f.p);
            if (e >= ull(f.exponent)) continue;
            ll denominator = unit(k, f) * unit(n - k, f) % f.q;
            ll residue =
                unit(n, f) * power(denominator, f.q - f.q / f.p - 1, f.q) % f.q;
            residue = residue * power(f.p, e, f.q) % f.q;
            answer = (answer + residue * f.crt) % mod;
        }
        return answer;
    }
};

int main()
{
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    unsigned long long n, m;
    int p;
    std::cin >> n >> m >> p;
    ExLucas comb(p);
    std::cout << comb.choose(n, m) << '\n';
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
vector<long long> mod_sqrt(long long n, int p)
{
    using ll = long long;
    assert(p >= 2);
    n = (n % p + p) % p;
    if (n == 0 || p == 2) return {n};
    auto power = [p](ll a, ll b)
    {
        ll result = 1;
        while (b)
        {
            if (b & 1) result = result * a % p;
            a = a * a % p;
            b >>= 1;
        }
        return result;
    };
    if (power(n, (p - 1) / 2) != 1) return {};
    ll answer;
    if (p % 4 == 3)
        answer = power(n, (ll(p) + 1) / 4);
    else
    {
        static mt19937_64 rng(712367);
        ll a, w;
        do
        {
            a = rng() % p;
            w = (a * a % p - n + p) % p;
        } while (power(w, (p - 1) / 2) != p - 1);
        using P = pair<ll, ll>;
        auto mul = [p, w](P x, P y)
        {
            ll real = (x.first * y.first + x.second * y.second % p * w) % p;
            ll imag = (x.first * y.second + x.second * y.first) % p;
            return P{real, imag};
        };
        P result{1, 0}, base{a, 1};
        ll exponent = (ll(p) + 1) / 2;
        while (exponent)
        {
            if (exponent & 1) result = mul(result, base);
            base = mul(base, base);
            exponent >>= 1;
        }
        answer = result.first;
    }
    ll other = p - answer;
    if (answer > other) swap(answer, other);
    return {answer, other};
}


