vector<long long> mod_sqrt(long long n, int p)
{
    using ll = long long;
    assert(p >= 2);
    n = (n % p + p) % p;
    if (n == 0 || p == 2) return {n};
    auto power = [p](ll a, ll b)
    {
        ll result = 1;
        while (b)
        {
            if (b & 1) result = result * a % p;
            a = a * a % p;
            b >>= 1;
        }
        return result;
    };
    if (power(n, (p - 1) / 2) != 1) return {};
    ll answer;
    if (p % 4 == 3)
        answer = power(n, (ll(p) + 1) / 4);
    else
    {
        static mt19937_64 rng(712367);
        ll a, w;
        do
        {
            a = rng() % p;
            w = (a * a % p - n + p) % p;
        } while (power(w, (p - 1) / 2) != p - 1);
        using P = pair<ll, ll>;
        auto mul = [p, w](P x, P y)
        {
            ll real = (x.first * y.first + x.second * y.second % p * w) % p;
            ll imag = (x.first * y.second + x.second * y.first) % p;
            return P{real, imag};
        };
        P result{1, 0}, base{a, 1};
        ll exponent = (ll(p) + 1) / 2;
        while (exponent)
        {
            if (exponent & 1) result = mul(result, base);
            base = mul(base, base);
            exponent >>= 1;
        }
        answer = result.first;
    }
    ll other = p - answer;
    if (answer > other) swap(answer, other);
    return {answer, other};
}


struct FpsSqrt : FpsInverse
{
    static optional<Poly> sqrt(const Poly &a, int n)
    {
        assert(n >= 0 && n <= max_size / 2);
        int k = 0;
        while (k < n && (k >= (int)a.size() || a[k].v == 0)) k++;
        if (k == n) return Poly(n);
        if (k & 1) return nullopt;
        auto roots = mod_sqrt(a[k].v, mod);
        if (roots.empty()) return nullopt;
        Poly b{Z(roots[0])};
        int target = n - k;
        while ((int)b.size() < target)
        {
            int m = min(target, 2 * (int)b.size());
            Poly f(a.begin() + k, a.begin() + min(k + m, (int)a.size()));
            auto t = multiply(f, inverse(b, m));
            t.resize(m);
            for (int i = 0; i < (int)b.size(); i++) t[i] += b[i];
            for (auto &x : t) x *= Z((mod + 1) / 2);
            b = move(t);
        }
        b.insert(b.begin(), k / 2, Z(0));
        b.resize(n);
        return b;
    }
};

