    };

    // m rows of n+1 characters: coefficients followed by the right-hand side.
    static Solution solve(const vector<string> &a, int n)
    {
        assert(n >= 0);
        int m = a.size(), w = n / 64 + 1, row = 0;
        vector<vector<unsigned long long>> b(m, vector<unsigned long long>(w));
        for (int i = 0; i < m; i++)
        {
            assert(a[i].size() == (size_t)n + 1);
            for (int j = 0; j <= n; j++)
            {
                assert(a[i][j] == '0' || a[i][j] == '1');
                if (a[i][j] == '1') b[i][j / 64] |= 1ULL << (j % 64);
            }
        }
        auto get = [&](int i, int j)
        {
            return b[i][j / 64] >> (j % 64) & 1;
        };
        vector<int> pos(n, -1);
        for (int col = 0; col < n && row < m; col++)
        {
            int p = row;
            while (p < m && !get(p, col)) p++;
            if (p == m) continue;
            swap(b[p], b[row]);
            for (int i = 0; i < m; i++)
                if (i != row && get(i, col))
                    for (int j = col / 64; j < w; j++) b[i][j] ^= b[row][j];
            pos[col] = row++;
        }
        for (int i = row; i < m; i++)
            if (get(i, n)) return {false, row, {}, {}};
        Solution ans{true, row, string(n, '0'), {}};
        for (int j = 0; j < n; j++)
            if (pos[j] != -1) ans.particular[j] += get(pos[j], n);
        for (int j = 0; j < n; j++)
            if (pos[j] == -1)
            {
                string v(n, '0');
                v[j] = '1';
                for (int k = 0; k < n; k++)
                    if (pos[k] != -1) v[k] += get(pos[k], j);
                ans.kernel.push_back(v);
            }
        return ans;
    }
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--)
    {
        int n;
        cin >> n;
        int m = n * n;
        vector<string> a(m, string(m + 1, '0'));
        vector<pair<int, int>> dir{{0, 0}, {0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        for (int i = 0; i < n; i++)
        {
            string s;
            cin >> s;
            for (int j = 0; j < n; j++)
            {
                int id = i * n + j;
                a[id][m] = s[j] == 'w' ? '1' : '0';
                for (auto [di, dj] : dir)
                {
                    int u = i + di, v = j + dj;
                    if (0 <= u && u < n && 0 <= v && v < n) a[id][u * n + v] = '1';
                }
            }
        }
        auto sol = GaussXor::solve(a, m);
        if (!sol.consistent)
        {
            cout << "inf\n";
            continue;
        }
        string x = sol.particular;
        int ans = m;
        function<void(int)> dfs = [&](int k)
        {
            if (k == (int)sol.kernel.size())
            {
                ans = min(ans, (int)count(x.begin(), x.end(), '1'));
                return;
            }
            dfs(k + 1);
            for (int j = 0; j < m; j++) x[j] ^= sol.kernel[k][j] - '0';
            dfs(k + 1);
            for (int j = 0; j < m; j++) x[j] ^= sol.kernel[k][j] - '0';
        };
        dfs(0);
        cout << ans << '\n';
    }
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct DivisionTree
{
    int n;
    vector<long long> sorted;
    vector<vector<long long>> a;
    vector<vector<int>> pre;

    DivisionTree(const vector<long long> &v) : n(v.size()), sorted(v)
    {
        sort(sorted.begin(), sorted.end());
        int h = bit_width((unsigned)max(1, n) - 1) + 1;
        a.assign(h, vector<long long>(n));
        pre.assign(h, vector<int>(n + 1));
        a[0] = v;
        if (n) build(0, n, 0);
    }

    void build(int l, int r, int d)
    {
        if (r - l == 1) return;
        int m = l + (r - l) / 2, same = m - l;
        for (int i = l; i < r; i++) same -= a[d][i] < sorted[m - 1];
        int x = l, y = m;
        for (int i = l; i < r; i++)
        {
            bool left = a[d][i] < sorted[m - 1];
            if (a[d][i] == sorted[m - 1] && same > 0)
            {
                left = true;
                same--;
            }
            if (left)
                a[d + 1][x++] = a[d][i];
            else
                a[d + 1][y++] = a[d][i];
            pre[d][i + 1] = pre[d][i] + left;
        }
        build(l, m, d + 1);
        build(m, r, d + 1);
    }

    long long query(int L, int R, int l, int r, int d, int k) const
    {
        if (r - l == 1) return a[d][l];
        int m = L + (R - L) / 2;
        int before = pre[d][l] - pre[d][L], cnt = pre[d][r] - pre[d][l];
        if (k < cnt) return query(L, m, L + before, L + before + cnt, d + 1, k);
        int x = m + (l - L - before);
        return query(m, R, x, x + (r - l - cnt), d + 1, k - cnt);
    }

    long long kth(int l, int r, int k) const
    {
        assert(0 <= l && l < r && r <= n && 0 <= k && k < r - l);
        return query(0, n, l, r, 0, k);
    }
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    DivisionTree tree(a);
    while (q--)
    {
        int l, r, k;
        cin >> l >> r >> k;
        cout << tree.kth(l - 1, r, k - 1) << '\n';
    }
}

