using namespace std;
struct IntegerPlane
{
    using ll = long long;
    using I = __int128_t;

    // Contract: |coordinate|<=1e12. Differences/products widened before arithmetic.
    struct Point
    {
        ll x = 0, y = 0;

        bool operator<(Point b) const { return tie(x, y) < tie(b.x, b.y); }

        bool operator==(Point b) const { return x == b.x && y == b.y; }
    };

    static I cross(Point a, Point b, Point c)
    {
        return (I(b.x) - a.x) * (I(c.y) - a.y) - (I(b.y) - a.y) * (I(c.x) - a.x);
    }

    static I dot(Point a, Point b, Point c)
    {
        return (I(b.x) - a.x) * (I(c.x) - a.x) + (I(b.y) - a.y) * (I(c.y) - a.y);
    }

    static I dist2(Point a, Point b) { return dot(a, b, b); }

    static int sign(I x) { return (x > 0) - (x < 0); }

    static bool on_segment(Point p, Point a, Point b)
    {
        return cross(a, b, p) == 0 && dot(p, a, b) <= 0;
    }

    static bool intersect(Point a, Point b, Point c, Point d)
    {
        int x = sign(cross(a, b, c)), y = sign(cross(a, b, d));
        int z = sign(cross(c, d, a)), w = sign(cross(c, d, b));
        if (!x && on_segment(c, a, b)) return true;
        if (!y && on_segment(d, a, b)) return true;
        if (!z && on_segment(a, c, d)) return true;
        if (!w && on_segment(b, c, d)) return true;
        return x * y < 0 && z * w < 0;
    }

    struct PolarLess
    {
        static int half(Point p) { return p.y < 0 || (p.y == 0 && p.x < 0); }

        bool operator()(Point a, Point b) const
        {
            if (half(a) != half(b)) return half(a) < half(b);
            I c = cross({0, 0}, a, b);
            if (c) return c > 0;
            return dist2({0, 0}, a) < dist2({0, 0}, b);
        }
    };
};

struct RealPlane
{
    using R = long double;

    struct Point
    {
        R x = 0, y = 0;

        Point operator+(Point b) const { return {x + b.x, y + b.y}; }

        Point operator-(Point b) const { return {x - b.x, y - b.y}; }

        Point operator*(R k) const { return {x * k, y * k}; }

        Point operator/(R k) const { return {x / k, y / k}; }
    };

    struct Circle
    {
        Point o;
        R r;
    };
    enum class Kind
    {
        none,
        one,
        two,
        infinite,
        degenerate
    };

    struct Result
    {
        Kind kind;
        vector<Point> p;
    };

    static R dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }

    static R cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }

    static R norm(Point a) { return hypotl(a.x, a.y); }

    static Point perp(Point a) { return {-a.y, a.x}; }
};

struct IntegerTangents
{
    using I = __int128_t;
    using R = RealPlane::R;
    using Point = IntegerPlane::Point;

    struct Tangent
    {
        RealPlane::Point a, b, normal;
        int side;
    };

    struct Result
    {
        bool infinite = false;
        vector<Tangent> lines;
    };

    static int sign(I x) { return (x > 0) - (x < 0); }

    // Internal: sign(a + b * sqrt(c)), c >= 0.
    static int root_sign(I a, I b, I c)
    {
        if (b == 0 || c == 0) return sign(a);
        if (a == 0 || sign(a) == sign(b)) return sign(b);
        return sign(a) * sign(a * a - b * b * c);
    }

    // Internal: sign(a + b * sqrt(c) + e * sqrt(f)).
    static int compare(I a, I b, I c, I e, I f)
    {
        int u = root_sign(a, b, c), v = f == 0 ? 0 : sign(e);
        if (u == 0) return v;
        if (v == 0 || u == v) return u;
        return u * root_sign(a * a + b * b * c - e * e * f, 2 * a * b, c);
    }

    // |coordinates| <= 10000, 0 <= radii <= 10000.
    // Lines are ordered by their exact contact (x, y) on the first circle.
    static Result solve(Point a, long long r, Point b, long long s)
    {
        for (auto p : {a, b})
            assert(-10000 <= p.x && p.x <= 10000 && -10000 <= p.y && p.y <= 10000);
        assert(0 <= r && r <= 10000 && 0 <= s && s <= 10000);
        I x = I(b.x) - a.x, y = I(b.y) - a.y;
        I q = x * x + y * y;
        if (q == 0) return {r == s, {}};
        RealPlane::Point v{R(x), R(y)}, o{R(a.x), R(a.y)}, p{R(b.x), R(b.y)};
        if (r == 0 && s == 0)
            return {false, {{o, p, RealPlane::perp(v) / sqrtl(R(q)), 0}}};

        struct Item
        {
            I g, d;
            int sign, side;
        };

        vector<Item> items;
        for (int side : {1, -1})
        {
            if (side == -1 && (r == 0 || s == 0)) continue;
            I g = I(r) - side * s, d = q - g * g;
            if (d < 0) continue;
            items.push_back({g, d, -1, side});
            if (d > 0) items.push_back({g, d, 1, side});
        }
        sort(items.begin(),
             items.end(),
             [&](Item a, Item b)
             {
                 int k = compare(x * (a.g - b.g), -y * a.sign, a.d, y * b.sign, b.d);
                 if (k != 0) return k < 0;
                 return compare(y * (a.g - b.g), x * a.sign, a.d, -x * b.sign, b.d) < 0;
             });
        Result answer;
        for (auto t : items)
        {
            auto n =
                (v * R(t.g) + RealPlane::perp(v) * (t.sign * sqrtl(R(t.d)))) / R(q);
            answer.lines.push_back({o + n * R(r), p + n * R(t.side * s), n, t.side});
        }
        return answer;
    }
};

