int main()
{
    int n, q;
    scanf("%d%d", &n, &q);
    vector<int> a(n), next(n), last(n + 1, n), version(n + 1);
    for (auto &x : a) scanf("%d", &x);
    for (int i = n - 1; i >= 0; i--)
    {
        next[i] = last[a[i]];
        last[a[i]] = i;
    }
    PersistentRange tree(n);
    function<size_t(int, int, int, int)> nodes =
        [&](int l, int r, int ql, int qr) -> size_t
    {
        if (qr <= l || r <= ql) return 0;
        if (ql <= l && r <= qr) return 1;
        int m = l + (r - l) / 2;
        return 1 + nodes(l, m, ql, qr) + nodes(m, r, ql, qr);
    };
    size_t capacity = 1;
    for (int i = 0; i < n; i++)
    {
        capacity += nodes(0, n, i, next[i]);
        capacity += nodes(0, n, next[i], n);
    }
    tree.t.reserve(capacity);
    tree.root.reserve(2 * n + 1);
    for (int i = n - 1; i >= 0; i--)
    {
        int p = next[i];
        int v = tree.add(version[i + 1], i, p, 1);
        version[i] = p == n ? v : tree.splice(v, version[p + 1], p, n);
    }
    int answer = 0;
    while (q--)
    {
        int l, r;
        scanf("%d%d", &l, &r);
        l ^= answer;
        r ^= answer;
        answer = tree.query(version[l - 1], r - 1, r);
        printf("%d\n", answer);
    }
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct XorBasis
{
    using U = unsigned long long;
    using Wide = __uint128_t;
    U a[64]{};
    vector<U> p;
    int rank = 0;
    bool dependent = false, dirty = false;

    bool insert(U x)
    {
        for (int i = 63; i >= 0; i--)
            if (x >> i & 1)
            {
                if (!a[i])
                {
                    a[i] = x;
                    rank++;
                    dirty = true;
                    return true;
                }
                x ^= a[i];
            }
        dependent = true;
        return false;
    }

    bool contains(U x) const
    {
        for (int i = 63; i >= 0; i--)
            if (x >> i & 1) x ^= a[i];
        return x == 0;
    }

    U query(U x = 0) const
    {
        for (int i = 63; i >= 0; i--) x = max(x, x ^ a[i]);
        return x;
    }

    void rebuild()
    {
        vector<U> b(a, a + 64);
        for (int i = 0; i < 64; i++)
            if (b[i])
                for (int j = i + 1; j < 64; j++)
                    if (b[j] >> i & 1) b[j] ^= b[i];
        p.clear();
        for (U x : b)
            if (x) p.push_back(x);
        dirty = false;
    }

    // k is 1-based; nonempty excludes the empty input subset, not value zero.
    optional<U> kth(Wide k, bool nonempty = true)
    {
        if (!k) return nullopt;
        Wide index = k;
        if (!nonempty || dependent) index--;
        if (index >= (Wide(1) << rank)) return nullopt;
        if (dirty) rebuild();
        U answer = 0;
        for (int i = 0; i < rank; i++)
            if (index >> i & 1) answer ^= p[i];
        return answer;
    }

    optional<U> minimum(bool nonempty = true) { return kth(1, nonempty); }

    void merge(const XorBasis &other)
    {
        dependent |= other.dependent;
        for (U x : other.a)
            if (x) insert(x);
    }
};

struct XorWalk
{
    using U = unsigned long long;
    int n;
    bool built = false;
    vector<vector<pair<int, U>>> g;
    vector<int> vis;
    vector<U> dist;
    XorBasis cycles;

    XorWalk(int size)
    {
        assert(size >= 0);
        n = size;
        g.resize(size_t(n) + 1);
        vis.resize(size_t(n) + 1);
        dist.resize(size_t(n) + 1);
    }

    void add(int u, int v, U w)
    {
        assert(1 <= u && u <= n && 1 <= v && v <= n);
        g[u].push_back({v, w});
        g[v].push_back({u, w});
        built = false;
    }

    void dfs(int u)
    {
        vis[u] = 1;
        for (auto [v, w] : g[u])
        {
            if (!vis[v])
            {
                dist[v] = dist[u] ^ w;
                dfs(v);
            }
            else
                cycles.insert(dist[u] ^ dist[v] ^ w);
        }
    }

    void build(int root = 1)
    {
        assert(1 <= root && root <= n);
        fill(vis.begin(), vis.end(), 0);
        fill(dist.begin(), dist.end(), 0);
        cycles = XorBasis();
        dfs(root);
        built = true;
    }

    optional<U> query(int u, int v) const
    {
        assert(built && 1 <= u && u <= n && 1 <= v && v <= n);
        if (!vis[u] || !vis[v]) return nullopt;
        return cycles.query(dist[u] ^ dist[v]);
    }
};

int main()
{
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n, m;
    std::cin >> n >> m;
    XorWalk graph(n);
    for (int i = 0; i < m; i++)
    {
        int u, v;
        unsigned long long w;
        std::cin >> u >> v >> w;
        graph.add(u, v, w);
    }
    graph.build(1);
    std::cout << *graph.query(1, n) << '\n';
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct UndirectedEuler
{
    int n;
    vector<vector<pair<int, int>>> g;
    vector<pair<int, int>> edges;
    vector<int> next, used, vertices, edge_ids;

    UndirectedEuler(int n) : n(n), g(n + 1), next(n + 1) { assert(n > 0); }

    int add(int u, int v)
    {
        assert(1 <= u && u <= n && 1 <= v && v <= n);
        int id = edges.size();
        edges.push_back({u, v});
        g[u].push_back({v, id});
        g[v].push_back({u, id});
        vertices.clear();
        edge_ids.clear();
        return id;
    }

    void dfs(int u, int incoming)
    {
        while (next[u] < (int)g[u].size())
        {
            auto [v, id] = g[u][next[u]++];
            if (used[id]) continue;
            used[id] = 1;
            dfs(v, id);
        }
        vertices.push_back(u);
        if (incoming != -1) edge_ids.push_back(incoming);
    }

    // start=0 chooses the smallest feasible start. Isolated vertices are ignored.
    bool run(int start = 0, bool lexicographic = true)
    {
        assert(0 <= start && start <= n);
        vertices.clear();
        edge_ids.clear();
        vector<int> odd;
        for (int u = 1; u <= n; u++)
            if (g[u].size() % 2) odd.push_back(u);
        if (!odd.empty() && odd.size() != 2) return false;
        if (!odd.empty())
        {
            if (start && start != odd[0] && start != odd[1]) return false;
            if (!start) start = odd[0];
        }
        if (!start)
        {
            start = 1;
            for (int u = 1; u <= n; u++)
                if (!g[u].empty())
                {
                    start = u;
                    break;
                }
        }
        if (lexicographic)
            for (int u = 1; u <= n; u++) sort(g[u].begin(), g[u].end());
        fill(next.begin(), next.end(), 0);
        used.assign(edges.size(), 0);
        dfs(start, -1);
        if (edge_ids.size() != edges.size())
        {
            vertices.clear();
            edge_ids.clear();
            return false;
        }
        reverse(vertices.begin(), vertices.end());
        reverse(edge_ids.begin(), edge_ids.end());
        return true;
    }
};

