int carmichael(int n)
{
    assert(n >= 1);
    long long answer = 1;
    for (int p = 2; p <= n / p; p++)
        if (n % p == 0)
        {
            int power = 1;
            while (n % p == 0)
            {
                n /= p;
                power *= p;
            }
            int value = power / p * (p - 1);
            if (p == 2 && power >= 8) value /= 2;
            answer = answer / gcd(answer, (long long)value) * value;
        }
    if (n > 1) answer = answer / gcd(answer, (long long)(n - 1)) * (n - 1);
    return answer;
}


int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    while (cin >> n && n)
    {
        bool special = !Prime64::prime(n) && (n - 1) % carmichael(n) == 0;
        if (special)
            cout << "The number " << n << " is a Carmichael number.\n";
        else
            cout << n << " is normal.\n";
    }
    return 0;
}

