pair<int, vector<array<bool, 2>>>
matching_edges(int n, int m, const vector<pair<int, int>> &edges)
{
    BipartiteMatching b(n, m);
    for (auto [u, v] : edges)
    {
        assert(1 <= u && u <= n && 1 <= v && v <= m);
        b.add(u, v);
    }
    int size = b.solve(), s = n + m + 1, t = s + 1;
    TarjanSCC d(t);
    for (int u = 1; u <= n; u++)
        if (b.l[u])
            d.add(u, s);
        else
            d.add(s, u);
    for (int v = 1; v <= m; v++)
        if (b.r[v])
            d.add(t, n + v);
        else
            d.add(n + v, t);
    vector<bool> chosen(n + 1), used(edges.size());
    for (int i = 0; i < (int)edges.size(); i++)
    {
        auto [u, v] = edges[i];
        used[i] = b.l[u] == v && !chosen[u];
        if (used[i])
        {
            chosen[u] = true;
            d.add(n + v, u);
        }
        else
            d.add(u, n + v);
    }
    d.run();
    vector<array<bool, 2>> ans(edges.size());
    for (int i = 0; i < (int)edges.size(); i++)
    {
        auto [u, v] = edges[i];
        bool same = d.bel[u] == d.bel[n + v];
        ans[i] = {used[i] || same, used[i] && !same};
    }
    return {size, ans};
}


int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    vector<pair<int, int>> edges(k);
    for (auto &[u, v] : edges) cin >> u >> v;
    auto [size, labels] = matching_edges(n, m, edges);
    cout << size << '\n';
    for (auto [possible, forced] : labels) cout << possible << ' ' << forced << '\n';
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct dsu
{
    vector<int> fa, sz;

    dsu(int n) : fa(n), sz(n, 1) { iota(fa.begin(), fa.end(), 0); }

    int find(int x)
    {
        while (x != fa[x]) x = fa[x] = fa[fa[x]];
        return x;
    }

    bool same(int x, int y) { return find(x) == find(y); }

    bool merge(int x, int y)
    {
        x = find(x), y = find(y);
        if (x == y) return false;
        sz[x] += sz[y], fa[y] = x;
        return true;
    }

    int size(int x) { return sz[find(x)]; }

    vector<vector<int>> groups()
    {
        vector<vector<int>> res(fa.size());
        for (int i = 0; i < int(fa.size()); i++) res[find(i)].push_back(i);
        res.erase(
            remove_if(res.begin(), res.end(), [&](const auto &v) { return v.empty(); }),
            res.end());
        return res;
    }
};


optional<vector<int>> odd_induced_partition(int n, const vector<pair<int, int>> &edges)
{
    vector<vector<int>> g(n), up(n);
    for (auto [u, v] : edges)
    {
        assert(0 <= u && u < n && 0 <= v && v < n && u != v);
        g[u].push_back(v);
        g[v].push_back(u);
    }
    vector<int> depth(n, -1), order;
    auto dfs = [&](auto &&self, int u, int h) -> int
    {
        depth[u] = h;
        int size = 1;
        for (int v : g[u])
            if (depth[v] == -1) size += self(self, v, h + 1);
        order.push_back(u);
        return size;
    };
    for (int u = 0; u < n; u++)
        if (depth[u] == -1 && dfs(dfs, u, 0) % 2) return nullopt;
    for (auto [u, v] : edges)
    {
        if (depth[u] > depth[v]) swap(u, v);
        up[v].push_back(u);
    }
    for (auto &a : up)
        sort(a.begin(), a.end(), [&](int u, int v) { return depth[u] < depth[v]; });
    dsu d(n);
    vector<int> level = depth, color(n);
    int count = 0;
    for (int u : order)
    {
        vector<int> children;
        for (int v : g[u])
            if (level[v] == level[u] + 1 && !color[d.find(v)]) children.push_back(v);
        if (children.empty()) continue;
        int skip = -1, best = -1;
        if (children.size() % 2 == 0)
            for (int v : children)
            {
                auto it = lower_bound(up[v].begin(),
                                      up[v].end(),
                                      depth[u],
                                      [&](int w, int h) { return depth[w] < h; });
                if (it != up[v].begin() && depth[*prev(it)] > best)
                {
                    skip = v;
                    best = depth[*prev(it)];
                }
            }
        if (skip != -1) level[skip] = best + 1;
        if (children.size() % 2 || skip != -1) color[d.find(u)] = ++count;
        for (int v : children)
            if (v != skip) d.merge(u, v);
    }
    for (int u = 0; u < n; u++) color[u] = color[d.find(u)];
    return color;
}


int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<pair<int, int>> edges(m);
    for (auto &[u, v] : edges)
    {
        cin >> u >> v;
        u--;
        v--;
    }
    auto color = odd_induced_partition(n, edges);
    if (!color)
        cout << -1 << '\n';
    else
    {
        for (int x : *color) cout << x << ' ';
        cout << '\n';
    }
}

