    }
    vector<int> sources(k), sinks(k);
    for (int &u : sources) cin >> u;
    for (int &u : sinks) cin >> u;
    auto ans = dag_path_determinant<998244353>(g, sources, sinks);
    if (!ans)
        cout << "CYCLE\n";
    else
        cout << ans->v << '\n';
}

