#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct SequenceTreap
{
    using ll = long long;

    struct Node
    {
        int l = 0, r = 0, siz = 0;
        ll val = 0, sum = 0, tag = 0;
        unsigned long long pri = 0;
        bool rev = false, neg = false;
    };

    vector<Node> a{Node{}};
    mt19937_64 rng;
    int root = 0;

    SequenceTreap(unsigned long long seed = 712367821) : rng(seed) {}

    int size() const { return a[root].siz; }

    void pull(int p)
    {
        a[p].siz = a[a[p].l].siz + a[a[p].r].siz + 1;
        a[p].sum = a[a[p].l].sum + a[p].val + a[a[p].r].sum;
    }

    void apply_add(int p, ll x)
    {
        if (!p) return;
        a[p].val += x;
        a[p].sum += x * a[p].siz;
        a[p].tag += x;
    }

    void apply_negate(int p)
    {
        if (!p) return;
        a[p].val = -a[p].val;
        a[p].sum = -a[p].sum;
        a[p].tag = -a[p].tag;
        a[p].neg = !a[p].neg;
    }

    void apply_reverse(int p)
    {
        if (!p) return;
        swap(a[p].l, a[p].r);
        a[p].rev = !a[p].rev;
    }

    void push(int p)
    {
        if (a[p].rev)
        {
            apply_reverse(a[p].l);
            apply_reverse(a[p].r);
            a[p].rev = false;
        }
        if (a[p].neg)
        {
            apply_negate(a[p].l);
            apply_negate(a[p].r);
            a[p].neg = false;
        }
        if (a[p].tag)
        {
            apply_add(a[p].l, a[p].tag);
            apply_add(a[p].r, a[p].tag);
            a[p].tag = 0;
        }
    }

    // Split into the first k elements and the rest.
    void split(int p, int k, int &l, int &r)
    {
        if (!p)
        {
            l = r = 0;
            return;
        }
        push(p);
        int left = a[a[p].l].siz;
        if (k > left)
        {
            l = p;
            split(a[p].r, k - left - 1, a[p].r, r);
        }
        else
        {
            r = p;
            split(a[p].l, k, l, a[p].l);
        }
        pull(p);
    }

    int merge(int l, int r)
    {
        if (!l || !r) return l ? l : r;
        if (a[l].pri > a[r].pri)
        {
            push(l);
            a[l].r = merge(a[l].r, r);
            pull(l);
            return l;
        }
        push(r);
        a[r].l = merge(l, a[r].l);
        pull(r);
        return r;
    }

    // Insert after the first k elements, 0 <= k <= size().
    void insert(int k, ll value)
    {
        assert(0 <= k && k <= size());
        int p = a.size(), l, r;
        a.push_back({0, 0, 1, value, value, 0, rng(), false, false});
        split(root, k, l, r);
        root = merge(merge(l, p), r);
    }

    // All range operations use 1-based inclusive intervals.
    void erase(int l, int r)
    {
        assert(1 <= l && l <= r && r <= size());
        int x, y, z;
        split(root, r, y, z);
        split(y, l - 1, x, y);
        root = merge(x, z);
    }

    void reverse(int l, int r)
    {
        assert(1 <= l && l <= r && r <= size());
        int x, y, z;
        split(root, r, y, z);
        split(y, l - 1, x, y);
        apply_reverse(y);
        root = merge(merge(x, y), z);
    }

    // Requires every value in [l,r] to be 0 or 1; preserves their order.
    void flip_bits(int l, int r)
    {
        assert(1 <= l && l <= r && r <= size());
        int x, y, z;
        split(root, r, y, z);
        split(y, l - 1, x, y);
        apply_negate(y);
        apply_add(y, 1);
        root = merge(merge(x, y), z);
    }

    void add(int l, int r, ll value)
    {
        assert(1 <= l && l <= r && r <= size());
        int x, y, z;
        split(root, r, y, z);
        split(y, l - 1, x, y);
        apply_add(y, value);
        root = merge(merge(x, y), z);
    }

    ll query(int l, int r)
    {
        assert(1 <= l && l <= r && r <= size());
        int x, y, z;
        split(root, r, y, z);
        split(y, l - 1, x, y);
        ll ans = a[y].sum;
        root = merge(merge(x, y), z);
        return ans;
    }

    void collect(int p, vector<ll> &out)
    {
        if (!p) return;
        push(p);
        collect(a[p].l, out);
        out.push_back(a[p].val);
        collect(a[p].r, out);
    }

    vector<ll> values()
    {
        vector<ll> answer;
        collect(root, answer);
        return answer;
    }
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    string s;
    cin >> n >> q >> s;
    SequenceTreap tree;
    for (int i = 0; i < n; i++) tree.insert(i, s[i] - '0');
    while (q--)
    {
        int l, r;
        cin >> l >> r;
        tree.flip_bits(l, r);
    }
    for (auto bit : tree.values()) cout << bit;
    cout << '\n';
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct ScapegoatTree
{
    using ll = long long;

    struct Node
    {
        int l = 0, r = 0, count = 0, size = 0, nodes = 0, live = 0;
        ll value = 0;
    };

    vector<Node> a{Node{}};
    int root = 0;

    int size() const { return a[root].size; }

    void pull(int p)
    {
        int l = a[p].l, r = a[p].r;
        a[p].size = a[l].size + a[r].size + a[p].count;
        a[p].nodes = a[l].nodes + a[r].nodes + 1;
        a[p].live = a[l].live + a[r].live + (a[p].count > 0);
    }

    void collect(int p, vector<int> &v)
    {
        if (!p) return;
        collect(a[p].l, v);
        if (a[p].count) v.push_back(p);
        collect(a[p].r, v);
    }

    int build(const vector<int> &v, int l, int r)
    {
        if (l == r) return 0;
        int m = l + (r - l) / 2, p = v[m];
        a[p].l = build(v, l, m);
        a[p].r = build(v, m + 1, r);
        pull(p);
        return p;
    }

    int balance(int p)
    {
        pull(p);
        int heavy = max(a[a[p].l].nodes, a[a[p].r].nodes);
        if (4LL * heavy <= 3LL * a[p].nodes && 2LL * a[p].live >= a[p].nodes) return p;
        vector<int> v;
        v.reserve(a[p].live);
        collect(p, v);
        return build(v, 0, v.size());
    }

    int insert(int p, ll x)
    {
        if (!p)
        {
            a.push_back({0, 0, 1, 1, 1, 1, x});
            return a.size() - 1;
        }
        if (x < a[p].value)
            a[p].l = insert(a[p].l, x);
        else if (x > a[p].value)
            a[p].r = insert(a[p].r, x);
        else
            a[p].count++;
        return balance(p);
    }

    int erase(int p, ll x, bool &found)
    {
        if (!p) return 0;
        if (x < a[p].value)
            a[p].l = erase(a[p].l, x, found);
        else if (x > a[p].value)
            a[p].r = erase(a[p].r, x, found);
        else if (a[p].count)
        {
            a[p].count--;
            found = true;
        }
        return balance(p);
    }

    void insert(ll x) { root = insert(root, x); }

    bool erase(ll x)
    {
        bool found = false;
        root = erase(root, x, found);
        return found;
    }

    int less(ll x, bool equal = false) const
    {
        int p = root, answer = 0;
        while (p)
        {
            if (a[p].value < x || (equal && a[p].value == x))
            {
                answer += a[a[p].l].size + a[p].count;
                p = a[p].r;
            }
            else
                p = a[p].l;
        }
        return answer;
    }

    int rank(ll x) const { return less(x) + 1; }

    ll kth(int k) const
    {
        assert(1 <= k && k <= size());
        int p = root;
        while (true)
        {
            int left = a[a[p].l].size;
            if (k <= left)
                p = a[p].l;
            else if (k <= left + a[p].count)
                return a[p].value;
            else
            {
                k -= left + a[p].count;
                p = a[p].r;
            }
        }
    }

    optional<ll> prev(ll x) const
    {
        int k = less(x);
        if (!k) return nullopt;
        return kth(k);
    }

    optional<ll> next(ll x) const
    {
        int k = less(x, true);
        if (k == size()) return nullopt;
        return kth(k + 1);
    }
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    ScapegoatTree g;
    while (n--)
    {
        int op;
        long long x;
        cin >> op >> x;
        if (op == 1)
            g.insert(x);
        else if (op == 2)
            g.erase(x);
        else if (op == 3)
            cout << g.rank(x) << '\n';
        else if (op == 4)
            cout << g.kth(x) << '\n';
        else if (op == 5)
            cout << *g.prev(x) << '\n';
        else
            cout << *g.next(x) << '\n';
    }
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
// Queries are 0-based half-open; count unordered pairs of distinct indices.
vector<long long> xor_hamming_pairs(const vector<int> &a,
                                    const vector<pair<int, int>> &queries,
                                    int k,
                                    int bits = 14)
{
    int n = a.size(), m = queries.size();
    vector<long long> answer(m);
    assert(0 <= bits && bits <= 20);
    int universe = 1 << bits;
    for (int x : a) assert(0 <= x && x < universe);
    for (auto [l, r] : queries) assert(0 <= l && l <= r && r <= n);
    if (!m || k < 0 || k > bits) return answer;
    vector<int> masks;
    for (int x = 0; x < universe; x++)
        if (popcount(unsigned(x)) == k) masks.push_back(x);
    vector<int> count(universe);
    vector<long long> prefix(n + 1);
    for (int i = 0; i < n; i++)
    {
        prefix[i + 1] = prefix[i] + count[a[i]];
        for (int mask : masks) count[a[i] ^ mask]++;
    }
    int block = max(1, int(n / sqrt(m)));
    vector<int> order(m);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(),
         order.end(),
         [&](int x, int y)
         {
             int bx = queries[x].first / block, by = queries[y].first / block;
             if (bx != by) return bx < by;
             return bx & 1 ? queries[x].second > queries[y].second
                           : queries[x].second < queries[y].second;
         });

    struct Event
    {
        int id, l, r, sign;
    };

    vector<vector<Event>> events(n + 1);
    int l = 0, r = 0;
    for (int id : order)
    {
        auto [ql, qr] = queries[id];
        if (r < qr)
        {
            events[l].push_back({id, r, qr, -1});
            answer[id] += prefix[qr] - prefix[r];
            r = qr;
        }
        if (l > ql)
        {
            events[r].push_back({id, ql, l, 1});
            answer[id] -= prefix[l] - prefix[ql];
            l = ql;
        }
        if (r > qr)
        {
            events[l].push_back({id, qr, r, 1});
            answer[id] -= prefix[r] - prefix[qr];
            r = qr;
        }
        if (l < ql)
        {
            events[r].push_back({id, l, ql, -1});
            answer[id] += prefix[ql] - prefix[l];
            l = ql;
        }
    }
    fill(count.begin(), count.end(), 0);
    for (int p = 0; p <= n; p++)
    {
        if (p)
            for (int mask : masks) count[a[p - 1] ^ mask]++;
        for (auto e : events[p])
            for (int i = e.l; i < e.r; i++)
            {
                int value = count[a[i]] - (k == 0 && i < p);
                answer[e.id] += 1LL * e.sign * value;
            }
    }
    long long total = 0;
    for (int id : order)
    {
        total += answer[id];
        answer[id] = total;
    }
    return answer;
}


int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    vector<int> a(n);
    for (int &x : a) cin >> x;
    vector<pair<int, int>> queries(m);
    for (auto &[l, r] : queries)
    {
        cin >> l >> r;
        l--;
    }
    for (long long x : xor_hamming_pairs(a, queries, k)) cout << x << '\n';
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct MonotoneStackSeg
{
    using ll = long long;

    struct Node
    {
        int len = 0;
        ll mx = 0, sum = 0, lazy = 0;
        array<ll, 2> fill{};
    };

    int n;
    vector<Node> t;

    MonotoneStackSeg(const vector<ll> &a) : n(a.size()), t(4 * n)
    {
        assert(n > 0);
        build(1, 0, n, a);
    }

    void apply(int p, ll delta)
    {
        t[p].mx += delta;
        t[p].sum += delta * t[p].len;
        t[p].lazy += delta;
    }

    void push(int p)
    {
        if (!t[p].lazy) return;
        apply(p * 2, t[p].lazy);
        apply(p * 2 + 1, t[p].lazy);
        t[p].lazy = 0;
    }

    ll extra(int p, ll height, int dir)
    {
        if (height >= t[p].mx) return height * t[p].len - t[p].sum;
        if (t[p].len == 1) return 0;
        push(p);
        int first = p * 2 + dir, second = p * 2 + 1 - dir;
        if (height >= t[first].mx)
            return height * t[first].len - t[first].sum + extra(second, height, dir);
        return extra(first, height, dir) + (t[p].fill[dir] - t[first].fill[dir]);
    }

    void pull(int p)
    {
        int l = p * 2, r = l + 1;
        t[p].len = t[l].len + t[r].len;
        t[p].mx = max(t[l].mx, t[r].mx);
        t[p].sum = t[l].sum + t[r].sum;
        t[p].fill[0] = t[l].fill[0] + extra(r, t[l].mx, 0);
        t[p].fill[1] = t[r].fill[1] + extra(l, t[r].mx, 1);
    }

    void build(int p, int l, int r, const vector<ll> &a)
    {
        if (r - l == 1)
        {
            t[p].len = 1;
            t[p].mx = a[l];
            t[p].sum = a[l];
            return;
        }
        int m = (l + r) / 2;
        build(p * 2, l, m, a);
        build(p * 2 + 1, m, r, a);
        pull(p);
    }

    void add(int p, int l, int r, int ql, int qr, ll delta)
    {
        if (ql <= l && r <= qr) return apply(p, delta);
        push(p);
        int m = (l + r) / 2;
        if (ql < m) add(p * 2, l, m, ql, qr, delta);
        if (m < qr) add(p * 2 + 1, m, r, ql, qr, delta);
        pull(p);
    }

    void add(int l, int r, ll delta)
    {
        assert(0 <= l && l <= r && r <= n);
        if (l < r) add(1, 0, n, l, r, delta);
    }

    ll scan(int p, int l, int r, int ql, int qr, ll &height, int dir)
    {
        if (ql <= l && r <= qr)
        {
            ll answer = extra(p, height, dir);
            height = max(height, t[p].mx);
            return answer;
        }
        push(p);
        int m = (l + r) / 2;
        ll answer = 0;
        if (dir && m < qr) answer += scan(p * 2 + 1, m, r, ql, qr, height, dir);
        if (ql < m) answer += scan(p * 2, l, m, ql, qr, height, dir);
        if (!dir && m < qr) answer += scan(p * 2 + 1, m, r, ql, qr, height, dir);
        return answer;
    }

    // Return (sum of running maximum - a[i], final running maximum).
    pair<ll, ll> scan(int l, int r, ll height, bool reverse = false)
    {
        assert(0 <= l && l <= r && r <= n);
        ll answer = 0;
        if (l < r) answer = scan(1, 0, n, l, r, height, reverse);
        return {answer, height};
    }

    ll water() const
    {
        ll gap = t[1].mx * n - t[1].sum;
        return t[1].fill[0] - (gap - t[1].fill[1]);
    }
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    MonotoneStackSeg s(a);
    cout << s.water() << '\n';
    while (q--)
    {
        int l, r;
        cin >> l >> r;
        s.add(l - 1, r, 1);
        cout << s.water() << '\n';
    }
}

