    cin >> n >> m;
    vector<int> a(n + 1), b(m + 1);
    for (int &x : a) cin >> x;
    for (int &x : b) cin >> x;
    auto c = convolution_fft(a, b);
    for (long long x : c) cout << x << ' ';
    cout << '\n';
}

