#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct Lowlink
{
    int n, timer = 0, components = 0;
    vector<vector<pair<int, int>>> g;
    vector<int> dfn, low, cut, bridge, delta;
    int edges = 0;

    Lowlink(int n) : n(n), g(n + 1) {}

    int add(int u, int v)
    {
        g[u].push_back({v, edges});
        g[v].push_back({u, edges});
        return edges++;
    }

    void dfs(int u, int pe)
    {
        dfn[u] = low[u] = ++timer;
        int children = 0;
        for (auto [v, id] : g[u])
        {
            if (id == pe) continue;
            if (!dfn[v])
            {
                ++children;
                dfs(v, id);
                low[u] = min(low[u], low[v]);
                if (low[v] > dfn[u]) bridge[id] = 1;
                if (pe != -1 && low[v] >= dfn[u])
                {
                    cut[u] = 1;
                    delta[u]++;
                }
            }
            else
                low[u] = min(low[u], dfn[v]);
        }
        if (pe == -1 && children > 1) cut[u] = 1;
        if (pe == -1) delta[u] = children - 1;
    }

    void run()
    {
        timer = 0;
        components = 0;
        dfn.assign(n + 1, 0);
        low = dfn;
        cut = dfn;
        delta = dfn;
        bridge.assign(edges, 0);
        for (int u = 1; u <= n; u++)
            if (!dfn[u])
            {
                components++;
                dfs(u, -1);
            }
    }
};

// Tree edges go down; other edges go to ancestors. Handles each logical edge once.
vector<pair<int, int>> orient_edges(const Lowlink &graph)
{
    vector<pair<int, int>> direction(graph.edges);
    vector<int> seen(graph.n + 1);
    auto dfs = [&](auto &&self, int u) -> void
    {
        seen[u] = 1;
        for (auto [v, id] : graph.g[u])
        {
            if (direction[id].first) continue;
            direction[id] = {u, v};
            if (!seen[v]) self(self, v);
        }
    };
    for (int u = 1; u <= graph.n; u++)
        if (!seen[u]) dfs(dfs, u);
    return direction;
}


int main()
{
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n, m;
    std::cin >> n >> m;
    Lowlink graph(n);
    for (int i = 0; i < m; i++)
    {
        int u, v;
        std::cin >> u >> v;
        graph.add(u, v);
    }
    graph.run();
    if (graph.components != 1 ||
        std::count(graph.bridge.begin(), graph.bridge.end(), 1))
    {
        std::cout << 0 << '\n';
        return 0;
    }
    for (auto [u, v] : orient_edges(graph)) std::cout << u << ' ' << v << '\n';
    return 0;
}

