#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct ComplexFFT
{
    using Real = long double;
    using C = complex<Real>;
    static constexpr int max_size = 1 << 22;
    int n;
    vector<C> roots;

    explicit ComplexFFT(int size) : n(size)
    {
        static_assert(numeric_limits<Real>::radix == 2);
        static_assert(numeric_limits<Real>::digits >= 53);
        assert(n > 0 && n <= max_size && (n & (n - 1)) == 0);
        roots.resize(n / 2);
        Real pi = acosl(-1);
        for (int i = 0; i < n / 2; i++)
        {
            Real angle = pi * (2.0L * i / n);
            roots[i] = C(cosl(angle), sinl(angle));
        }
    }

    void transform(vector<C> &a, bool inverse = false) const
    {
        assert(a.size() == (unsigned)n);
        for (int i = 1, j = 0; i < n; i++)
        {
            int bit = n >> 1;
            for (; j & bit; bit >>= 1) j ^= bit;
            j ^= bit;
            if (i < j) swap(a[i], a[j]);
        }
        for (int half = 1; half < n; half *= 2)
        {
            int step = n / (2 * half);
            for (int i = 0; i < n; i += 2 * half)
            {
                for (int j = 0; j < half; j++)
                {
                    C w = roots[j * step];
                    if (inverse) w = conj(w);
                    C u = a[i + j], v = a[i + j + half] * w;
                    a[i + j] = u + v;
                    a[i + j + half] = u - v;
                }
            }
        }
        if (inverse)
            for (auto &x : a) x /= n;
    }
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    int size = 1;
    while (size < n + m + 1) size *= 2;
    auto fft = ComplexFFT(size);
    vector<ComplexFFT::C> a(size), b(size);
    for (int i = 0, x; i <= n; i++) cin >> x, a[i] = x;
    for (int i = 0, x; i <= m; i++) cin >> x, b[i] = x;
    fft.transform(a);
    fft.transform(b);
    for (int i = 0; i < size; i++) a[i] *= b[i];
    fft.transform(a, true);
    for (int i = 0; i <= n + m; i++) cout << llroundl(a[i].real()) << ' ';
    cout << '\n';
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct MaxPlusMatrix
{
    using I = __int128_t;
    static constexpr I neg = -(I(1) << 120);
    int n;
    vector<vector<I>> a;

    MaxPlusMatrix(int n, bool identity = false) : n(n), a(n, vector<I>(n, neg))
    {
        if (identity)
            for (int i = 0; i < n; i++) a[i][i] = 0;
    }

    MaxPlusMatrix operator*(const MaxPlusMatrix &b) const
    {
        assert(n == b.n);
        MaxPlusMatrix c(n);
        for (int i = 0; i < n; i++)
            for (int k = 0; k < n; k++)
                if (a[i][k] != neg)
                    for (int j = 0; j < n; j++)
                        if (b.a[k][j] != neg)
                            c.a[i][j] = max(c.a[i][j], a[i][k] + b.a[k][j]);
        return c;
    }

    MaxPlusMatrix power(unsigned long long e) const
    {
        MaxPlusMatrix b = *this, r(n, true);
        for (; e; e >>= 1, b = b * b)
            if (e & 1) r = r * b;
        return r;
    }
};


int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    unsigned long long k;
    if (!(cin >> n >> m >> k)) return 0;
    MaxPlusMatrix a(n);
    for (int i = 0; i < m; i++)
    {
        int u, v;
        long long c;
        cin >> u >> v >> c;
        --u, --v;
        a.a[u][v] = max(a.a[u][v], -MaxPlusMatrix::I(c));
    }
    auto r = a.power(k);
    auto x = r.a[0][n - 1];
    // Official bounds imply each finite answer is in [1, 10^18].
    if (x == MaxPlusMatrix::neg) cout << -1 << '\n';
    else cout << (long long)(-x) << '\n';
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct GcdSequenceTreap
{
    using U = unsigned long long;

    struct Node
    {
        int l = 0, r = 0, siz = 0, tag = 0;
        int cnt[2]{};
        U val = 0, g[2]{}, pri = 0;
    };

    vector<Node> a{Node{}};
    vector<int> recycled;
    mt19937_64 rng;
    int root = 0;

    GcdSequenceTreap(U seed = 712367821) : rng(seed) {}

    int size() const { return a[root].siz; }

    int node(U value, int tag)
    {
        assert(tag == 0 || tag == 1);
        int p;
        if (recycled.empty())
        {
            p = a.size();
            a.push_back(Node{});
        }
        else
        {
            p = recycled.back();
            recycled.pop_back();
            a[p] = Node{};
        }
        a[p].siz = 1;
        a[p].val = value;
        a[p].tag = tag;
        a[p].cnt[tag] = 1;
        a[p].g[tag] = value;
        a[p].pri = rng();
        return p;
    }

    void pull(int p)
    {
        int l = a[p].l, r = a[p].r;
        a[p].siz = a[l].siz + a[r].siz + 1;
        for (int t = 0; t < 2; t++)
        {
            a[p].cnt[t] = a[l].cnt[t] + a[r].cnt[t] + (a[p].tag == t);
            a[p].g[t] = gcd(a[l].g[t], a[r].g[t]);
            if (a[p].tag == t) a[p].g[t] = gcd(a[p].g[t], a[p].val);
        }
    }

    void split(int p, int k, int &l, int &r)
    {
        if (!p)
        {
            l = 0;
            r = 0;
            return;
        }
        int left = a[a[p].l].siz;
        if (k > left)
        {
            l = p;
            split(a[p].r, k - left - 1, a[p].r, r);
        }
        else
        {
            r = p;
            split(a[p].l, k, l, a[p].l);
        }
        pull(p);
    }

    int merge(int l, int r)
    {
        if (!l || !r) return l ? l : r;
        if (a[l].pri > a[r].pri)
        {
            a[l].r = merge(a[l].r, r);
            pull(l);
            return l;
        }
        a[r].l = merge(l, a[r].l);
        pull(r);
        return r;
    }

    void rebuild(int p)
    {
        if (!p) return;
        rebuild(a[p].l);
        rebuild(a[p].r);
        pull(p);
    }

    void release(int p)
    {
        if (!p) return;
        release(a[p].l);
        release(a[p].r);
        recycled.push_back(p);
    }

    // O(n) GCD calls; replaces the current sequence.
    void build(const vector<pair<U, int>> &v)
    {
        a.assign(1, Node{});
        recycled.clear();
        root = 0;
        vector<int> st;
        for (auto [value, tag] : v)
        {
            int p = node(value, tag), last = 0;
            while (!st.empty() && a[st.back()].pri < a[p].pri)
            {
                last = st.back();
                st.pop_back();
            }
            a[p].l = last;
            if (!st.empty()) a[st.back()].r = p;
            st.push_back(p);
        }
        if (st.empty()) return;
        root = st.front();
        rebuild(root);
    }

    // Insert after the first k entries. Range operations below are 1-based.
    void insert(int k, U value, int tag)
    {
        assert(0 <= k && k <= size());
        int p = node(value, tag), l, r;
        split(root, k, l, r);
        root = merge(merge(l, p), r);
    }

    void erase(int l, int r)
    {
        assert(1 <= l && l <= r && r <= size());
        int x, y, z;
        split(root, r, y, z);
        split(y, l - 1, x, y);
        root = merge(x, z);
        release(y);
    }

    void set(int k, U value)
    {
        assert(1 <= k && k <= size());
        int x, y, z;
        split(root, k, y, z);
        split(y, k - 1, x, y);
        a[y].val = value;
        pull(y);
        root = merge(merge(x, y), z);
    }

    void toggle(int k)
    {
        assert(1 <= k && k <= size());
        int x, y, z;
        split(root, k, y, z);
        split(y, k - 1, x, y);
        a[y].tag ^= 1;
        pull(y);
        root = merge(merge(x, y), z);
    }

    optional<U> query(int l, int r, int tag)
    {
        assert(1 <= l && l <= r && r <= size());
        assert(tag == 0 || tag == 1);
        int x, y, z;
        split(root, r, y, z);
        split(y, l - 1, x, y);
        optional<U> answer;
        if (a[y].cnt[tag]) answer = a[y].g[tag];
        root = merge(merge(x, y), z);
        return answer;
    }
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    if (!(cin >> n >> q)) return 0;
    vector<pair<GcdSequenceTreap::U, int>> a(n);
    for (auto &[v, t] : a) cin >> v >> t;
    GcdSequenceTreap tr;
    tr.build(a);
    while (q--)
    {
        char op;
        int k, l, r, t;
        GcdSequenceTreap::U v;
        cin >> op;
        if (op == 'I')
        {
            cin >> k >> v >> t;
            tr.insert(k, v, t);
        }
        else if (op == 'E')
        {
            cin >> l >> r;
            tr.erase(l, r);
        }
        else if (op == 'S')
        {
            cin >> k >> v;
            tr.set(k, v);
        }
        else if (op == 'T')
        {
            cin >> k;
            tr.toggle(k);
        }
        else if (op == 'Q')
        {
            cin >> l >> r >> t;
            auto ans = tr.query(l, r, t);
            if (ans) cout << *ans << '\n';
            else cout << "NONE\n";
        }
    }
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;
struct IntegerGeometry3D
{
    using I = __int128_t;

    // |coordinates|<=1e9: triple products fit signed int128.
    struct Point
    {
        long long x, y, z;
    };

    struct Vector
    {
        I x, y, z;
    };

    static Vector diff(Point a, Point b)
    {
        return {I(a.x) - b.x, I(a.y) - b.y, I(a.z) - b.z};
    }

    static Vector cross(Vector a, Vector b)
    {
        return {a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x};
    }

    static I dot(Vector a, Vector b) { return a.x * b.x + a.y * b.y + a.z * b.z; }

    static I orient(Point a, Point b, Point c, Point d)
    {
        return dot(cross(diff(b, a), diff(c, a)), diff(d, a));
    }

    static bool collinear(Point a, Point b, Point c)
    {
        auto v = cross(diff(b, a), diff(c, a));
        return !v.x && !v.y && !v.z;
    }

    static bool on_segment(Point p, Point a, Point b)
    {
        return collinear(p, a, b) && dot(diff(a, p), diff(b, p)) <= 0;
    }
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    auto print = [](__int128_t x)
    {
        // Unsigned subtraction also handles the minimum signed int128 value.
        __uint128_t u = x < 0 ? __uint128_t(0) - __uint128_t(x) : __uint128_t(x);
        string s;
        do { s += char('0' + u % 10); u /= 10; } while (u);
        if (x < 0) cout << '-';
        reverse(s.begin(), s.end());
        cout << s;
    };
    int q;
    if (!(cin >> q)) return 0;
    while (q--)
    {
        IntegerGeometry3D::Point a, b, c, d;
        for (auto p : {&a, &b, &c, &d}) cin >> p->x >> p->y >> p->z;
        print(IntegerGeometry3D::orient(a, b, c, d));
        cout << ' ' << IntegerGeometry3D::collinear(a, b, c)
             << ' ' << IntegerGeometry3D::on_segment(d, a, b) << '\n';
    }
}

